#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        // [0..x-1] [x..n-1-y] [n-y..n-1] -> [suffix(y) middle prefix(x)]
        vector<int> res;
        for(int i = n-y; i < n; i++) res.push_back(p[i]);
        for(int i = x; i < n-y; i++) res.push_back(p[i]);
        for(int i = 0; i < x; i++) res.push_back(p[i]);
        p = res;
        ops.push_back({x, y});
    };

    for(int i = 0; i < n; i++){
        // Find where value i+1 is
        int j = -1;
        for(int k = 0; k < n; k++) if(p[k] == i+1){ j = k; break; }
        if(j == i) continue;

        // Step 1: Move element at position j to position n-1
        if(j < n-1){
            // x = j+1, y = 0 would not work (y >= 1 implied? no, x+y < n, x,y >= 1? Let's check)
            // Actually constraint is x >= 1, y >= 1, x + y < n (from typical problem statements)
            // Move to position 0 first: x = j, y = n-1-j, need x>=1,y>=1,x+y<n => j>=1, n-1-j>=1 => j<=n-2, j+n-1-j=n-1<n ok
            if(j > 0 && j < n-1){
                // This puts p[j] at position n-1-j
                apply(j, n-1-j);
                // Find it again
                for(int k = 0; k < n; k++) if(p[k] == i+1){ j = k; break; }
                if(j == i) continue;
            }
            // Now j is 0 or n-1
            if(j == 0 && n >= 3){
                // move position 0 to position n-1: x=1, y=1 (need 1+1<n => n>2)
                // [p[0]] [p[1]..p[n-2]] [p[n-1]] -> [p[n-1], p[1]..p[n-2], p[0]]
                apply(1, 1);
                j = n-1;
            }
        }
        // Now element is at position n-1 (or already at i)
        for(int k = 0; k < n; k++) if(p[k] == i+1){ j = k; break; }
        if(j == i) continue;

        // Step 2: Move from position n-1 to position i
        // x = i, y = 1: [prefix(i) | middle | last] -> [last, middle, prefix(i)]
        // element goes to position 0. But we want position i.
        // x = i+1, y = 1, need i+1+1 < n => i < n-2
        if(j == n-1 && i < n-2){
            // [prefix(i+1) | middle(n-i-2) | last] -> [last, middle, prefix(i+1)]
            // element at position 0, then need to shift? No: element goes to pos 0, but we want pos i.
            // Actually: x=n-1-i, y=1, need n-i<n always. Result: [p[n-1], p[n-1-i..n-2], p[0..n-2-i]]
            // p[n-1] goes to position 0... 
            // Use: x=i+1, y=1 => [last, p[i+1..n-2], p[0..i]] => element at position 0
            apply(i+1, 1);
            // Now at position 0, want position i. x=1, y=n-1-i
            if(i > 0)
                apply(1, n-1-i);
        } else if(j == n-1 && i == n-2 && n >= 3){
            apply(n-1, 1);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n", a, b);
}
